code_example:
#include <iostream>
#include <set>
#include <map>

int main() {
    // Declare a const std::set of integers (elements are constant)
    const std::set<int> mySet = {1, 2, 3, 4, 5};
    // Declare a const std::map with constant keys and values
    const std::map<std::string, int> myMap = {{"apple", 1}, {"banana", 2}};

    // Forward iteration over the set
    for (auto it = mySet.begin(); it != mySet.end(); ++it) {
        std::cout << *it << ' ';
    }
    std::cout << '\n';

    // Reverse iteration over the map (via reverse iterators)
    for (auto rit = myMap.rbegin(); rit != myMap.rend(); ++rit) {
        std::cout << rit->first << ':' << rit->second << ' ';
    }
    std::cout << '\n';
    return 0;
}
